def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted((list(pair) for pair in intervals), key=lambda x: x[0])
    merged = [sorted_intervals[0][:]]
    for start, end in sorted_intervals[1:]:
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
```

